starterCodeJson.code:
type Booking = { id: string; seats: number };
const store: Booking[] = [{ id: 'bk_1', seats: 40 }];
// The lookup may miss, but the return type promises a Booking.
export function bookingById(id: string): Booking {
  return store.find((b) => b.id === id);
}

import { bookingById } from '../src/service.ts';
const seats: number = bookingById('bk_1')?.seats ?? 0;
export { seats };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { bookingById } from '../src/service.ts';
test('bookingById', () => { assert.equal(bookingById('bk_1')?.seats, 40); assert.equal(bookingById('nope'), undefined); });

